using System.Security.Cryptography;using System.Text;using System.Text.Json;using Nd30.LegalValidator.Authorization;
namespace Nd30.LegalValidator.Execution;
public enum ConflictClass{INDEPENDENT,DUPLICATE,CONFLICTING,UNSUPPORTED_UNRESOLVABLE}
internal sealed record PlanOperation(string AuthorizedRequestId,string MutationIntentId,string ProposalId,string AuthorizationId,string RuleId,string FindingReference,IReadOnlyList<string> EvidenceReferences,string PartUri,string TargetPath,string Property,string Provenance,string ExpectedBefore,string DesiredAfter){public string SemanticKey=>string.Join("|",AuthorizedRequestId,MutationIntentId,ProposalId,AuthorizationId,RuleId,FindingReference,string.Join(",",EvidenceReferences.OrderBy(x=>x)),PartUri,TargetPath,Property,Provenance,ExpectedBefore,DesiredAfter);public string TargetProperty=>string.Join("|",PartUri,TargetPath,Property);}
public sealed record AuthorizedPlanOperation{internal PlanOperation Value{get;}internal AuthorizedPlanOperation(PlanOperation value)=>Value=value;public string RequestId=>Value.AuthorizedRequestId;public string Property=>Value.Property;public string TargetPath=>Value.TargetPath;public string ExpectedBefore=>Value.ExpectedBefore;public string DesiredAfter=>Value.DesiredAfter;public string RuleId=>Value.RuleId;public string FindingReference=>Value.FindingReference;public static AuthorizedPlanOperation From(AuthorizedMutationRequest q){if(q.StateBinding is null||q.Authorization is null||q.Authorization.Scope!="single-exact-mutation-intent")throw new ArgumentException("Exact authorized request required.");if(q.Intent is not null){var i=q.Intent;if(q.Authorization.MutationIntentId!=i.MutationIntentId||q.ProposalId!=i.ProposalId||q.StateBinding!=i.StateBinding||q.RuleId!=i.RuleId||q.FindingReference!=i.FindingReference||!q.EvidenceReferences.SequenceEqual(i.EvidenceReferences))throw new ArgumentException("Authorized request/intention binding mismatch.");return new AuthorizedPlanOperation(new PlanOperation(q.RequestId,i.MutationIntentId,i.ProposalId,q.Authorization.AuthorizationId,i.RuleId,i.FindingReference,i.EvidenceReferences,i.Target.PartUri,i.Target.StructuralPath,i.Property,"DIRECT",i.ExpectedBefore.ToString(),i.DesiredAfter.ToString()));}if(q.V26Intent is not null){var i=q.V26Intent;var exact=AuthorizationArtifact.H(string.Join("|","v26-spacing",i.ProposalId,i.StateBinding.ExpectedDocument.Digest,i.RuleId,i.FindingReference,i.TargetPath,i.Property,i.Provenance,i.ExpectedBefore,i.DesiredAfter));if(exact!=i.MutationIntentId)throw new ArgumentException("V26 intent identity/semantics mismatch.");if(q.Authorization.MutationIntentId!=i.MutationIntentId||q.ProposalId!=i.ProposalId||q.StateBinding!=i.StateBinding||q.RuleId!=i.RuleId||q.FindingReference!=i.FindingReference||!q.EvidenceReferences.SequenceEqual(i.EvidenceReferences))throw new ArgumentException("Authorized request/V26 intent binding mismatch.");return new AuthorizedPlanOperation(new PlanOperation(q.RequestId,i.MutationIntentId,i.ProposalId,q.Authorization.AuthorizationId,i.RuleId,i.FindingReference,i.EvidenceReferences,i.PartUri,i.TargetPath,i.Property,i.Provenance,i.ExpectedBefore,i.DesiredAfter));}throw new ArgumentException("Unbound authorized request.");}}
public sealed record MutationPlan{public string PlanId{get;}public string InputDocumentDigest{get;}public IReadOnlyList<AuthorizedPlanOperation> Operations{get;}public IReadOnlyList<ConflictClass> Classifications{get;}public bool HasConflict{get;}private MutationPlan(string id,string digest,IReadOnlyList<AuthorizedPlanOperation> ops,IReadOnlyList<ConflictClass> c,bool conflict)=>(PlanId,InputDocumentDigest,Operations,Classifications,HasConflict)=(id,digest,ops,c,conflict);public static MutationPlan Create(IEnumerable<AuthorizedMutationRequest> requests){var raw=requests.Select(AuthorizedPlanOperation.From).ToList();if(raw.Count==0)throw new ArgumentException("At least one authorized request required.");var digests=requests.Select(x=>x.StateBinding.ExpectedDocument.Digest).Distinct(StringComparer.Ordinal).ToList();if(digests.Count!=1)throw new ArgumentException("All requests must bind the same document state.");var values=raw.Select(x=>x.Value).ToList();if(values.Any(x=>x.Provenance!="DIRECT"||x.Property is not("paragraph.alignment" or "paragraph.spacing.after")||string.IsNullOrWhiteSpace(x.ExpectedBefore)||string.IsNullOrWhiteSpace(x.DesiredAfter)))throw new ArgumentException("Unsupported authorized operation.");var classes=new List<ConflictClass>();var ops=new List<PlanOperation>();foreach(var g in values.GroupBy(x=>x.TargetProperty,StringComparer.Ordinal).OrderBy(x=>x.Key,StringComparer.Ordinal)){var semantic=g.GroupBy(x=>x.SemanticKey,StringComparer.Ordinal).Select(x=>x.First()).OrderBy(x=>x.SemanticKey,StringComparer.Ordinal).ToList();if(g.Count()>semantic.Count)classes.Add(ConflictClass.DUPLICATE);if(semantic.Select(x=>x.DesiredAfter).Distinct(StringComparer.Ordinal).Count()>1){classes.Add(ConflictClass.CONFLICTING);ops.AddRange(semantic);continue;}classes.Add(ConflictClass.INDEPENDENT);ops.Add(semantic[0]);}ops=ops.OrderBy(x=>x.TargetProperty,StringComparer.Ordinal).ThenBy(x=>x.SemanticKey,StringComparer.Ordinal).ToList();var id=H(string.Join("\n",ops.Select(x=>x.SemanticKey).Prepend(digests[0])));return new(id,digests[0],ops.Select(x=>new AuthorizedPlanOperation(x)).ToList(),classes,classes.Contains(ConflictClass.CONFLICTING));}internal static string H(string s)=>Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(s))).ToLowerInvariant()[..32];}
public enum ExecutionStatus{PENDING,EXECUTING,SUCCEEDED,FAILED,REJECTED}public enum JournalDecision{STARTED,ALREADY_EXECUTED,IDEMPOTENCY_CONFLICT,PREVIOUS_FAILED}
public sealed record ExecutionOperation(string RequestId,string MutationIntentId,string RuleId,string FindingReference,string TargetPath,string Property,string ExpectedBefore,string DesiredAfter);
public sealed record ExecutionRecord(string ExecutionId,string IdempotencyKey,string SemanticDigest,string PlanId,string RequestId,string InputDigest,ExecutionStatus Status,IReadOnlyList<ExecutionOperation> Operations,string? OutputDigest=null,string? OutputReference=null,string? Failure=null,DateTimeOffset? UpdatedAt=null);public sealed record JournalBeginResult(JournalDecision Decision,ExecutionRecord? Record);public sealed class JournalException(string message):Exception(message);
public sealed class FileExecutionJournal:IDisposable{readonly string file;readonly object gate=new();public FileExecutionJournal(string directory){Directory.CreateDirectory(directory);file=Path.Combine(directory,"journal.json");}public JournalBeginResult Begin(string key,MutationPlan plan,string requestId,string inputDigest){lock(gate){var all=Load();var semantic=MutationPlan.H(string.Join("|",plan.PlanId,requestId,inputDigest));var prior=all.FirstOrDefault(x=>x.IdempotencyKey==key);if(prior is not null){if(prior.SemanticDigest!=semantic)return new(JournalDecision.IDEMPOTENCY_CONFLICT,prior);return prior.Status switch{ExecutionStatus.SUCCEEDED=>new(JournalDecision.ALREADY_EXECUTED,prior),ExecutionStatus.FAILED=>new(JournalDecision.PREVIOUS_FAILED,prior),_=>new(JournalDecision.ALREADY_EXECUTED,prior)};}var id=MutationPlan.H(string.Join("|","execution",key,semantic));var audit=plan.Operations.Select(x=>x.Value).Select(x=>new ExecutionOperation(x.AuthorizedRequestId,x.MutationIntentId,x.RuleId,x.FindingReference,x.TargetPath,x.Property,x.ExpectedBefore,x.DesiredAfter)).ToList();var r=new ExecutionRecord(id,key,semantic,plan.PlanId,requestId,inputDigest,ExecutionStatus.EXECUTING,audit,UpdatedAt:DateTimeOffset.UtcNow);all.Add(r);Save(all);return new(JournalDecision.STARTED,r);}}public void Succeed(string id,string outputDigest,string outputReference)=>Update(id,x=>x with{Status=ExecutionStatus.SUCCEEDED,OutputDigest=outputDigest,OutputReference=outputReference,UpdatedAt=DateTimeOffset.UtcNow});public void Fail(string id,string reason)=>Update(id,x=>x with{Status=ExecutionStatus.FAILED,Failure=reason,UpdatedAt=DateTimeOffset.UtcNow});public ExecutionRecord? Get(string id)=>Load().FirstOrDefault(x=>x.ExecutionId==id);void Update(string id,Func<ExecutionRecord,ExecutionRecord> f){lock(gate){var a=Load();var n=a.FindIndex(x=>x.ExecutionId==id);if(n<0)throw new JournalException("Execution not found.");a[n]=f(a[n]);Save(a);}}List<ExecutionRecord> Load(){if(!File.Exists(file))return[];try{return JsonSerializer.Deserialize<List<ExecutionRecord>>(File.ReadAllText(file))??throw new Exception();}catch(Exception e){throw new JournalException("Journal corrupt: "+e.Message);}}void Save(List<ExecutionRecord> a){var tmp=file+"."+Guid.NewGuid().ToString("N")+".tmp";try{File.WriteAllText(tmp,JsonSerializer.Serialize(a));File.Move(tmp,file,true);}catch(Exception e){try{File.Delete(tmp);}catch{}throw new JournalException("Journal write failed: "+e.Message);}}public void Dispose(){}}
